fn append_array(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Pre-allocate enough space for both a and b to avoid repeated reallocations
    let mut c = a;
    c.reserve(b.len());
    // Extend c with all elements of b
    c.extend(b);
    c
}

